-- Phase 5: canonical original educational lessons + approved live library.
-- Apply ONCE after 005_review_publication_workflow.sql. No existing draft,
-- published revision, profile, auth user, or audit event is updated/deleted.
-- The imported teaching text is the complete, unchanged web/src/data/seed-algorithms.json
-- snapshot of seven manually reviewed Fonctions V1 modules.
-- No contributor-provided Python is executable via the public FastAPI engine.

CREATE TABLE public.legacy_lessons (
  slug text PRIMARY KEY REFERENCES public.topics(slug),
  payload jsonb NOT NULL,
  source_credit text NOT NULL DEFAULT 'Fonctions V1 · Collection pédagogique d’origine',
  source_sha256 text NOT NULL CHECK (source_sha256 ~ '^[0-9a-f]{64}$'),
  imported_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT legacy_payload_schema CHECK (
    jsonb_typeof(payload) = 'object'
    AND payload->>'slug' = slug
    AND payload->>'method' = 'base'
    AND jsonb_typeof(payload->'code_sections') = 'array'
    AND jsonb_typeof(payload->'inputs') = 'array'
  )
);
ALTER TABLE public.legacy_lessons ENABLE ROW LEVEL SECURITY;
CREATE POLICY legacy_lessons_public_read ON public.legacy_lessons
  FOR SELECT TO anon, authenticated USING (true);
REVOKE ALL ON public.legacy_lessons FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.legacy_lessons TO anon, authenticated;

-- SQL seed is deliberately idempotent and does not overwrite prior lessons.
-- Track originals separately from user-authored revisions so we do not forge
-- reviewers, contributor test attestations or auth profiles for old material.
INSERT INTO public.legacy_lessons(slug,payload,source_sha256) VALUES
  ('enregistrement', $afjlesson${"slug":"enregistrement","name":"ENREGISTREMENT","title":"Valeurs nommées et typées","category":"Structures de données","level":"Bases · 3ème Info","method":"base","collection":"general","icon":"🗂️","summary":"Définir des champs nommés avec des valeurs de types différents.","principle":"Associer un nom, un type et une valeur à chaque champ, puis les regrouper. Ici, la représentation Python est un dictionnaire.","example":"nom = '3mor' · age = 17 · admis = Vrai","tags":["enregistrement","types","champs"],"limits":"Les noms de champs doivent être uniques et valides. Démonstration via un dictionnaire Python.","inputs":[{"name":"champs","label":"Champs de l'enregistrement","kind":"records","default":[["nom","chaîne","3mor"],["age","entier","17"],["admis","booléen","Vrai"]],"min_value":null,"max_value":null,"options":[],"hint":""}],"code_sections":[{"title":"Déclarer un enregistrement — TDNT et TDOG","pseudocode":"TDNT (Tableau de Déclaration des Nouveaux Types)\n    Eleve = Enregistrement\n        nom : Chaîne\n        age : Entier\n        admis : Booléen\n    Fin\n\nTDOG (Tableau de Déclaration des Objets Globaux)\n    Objet       Type / Nature\n    E           Eleve","python":"E = {\n    \"nom\": str(),\n    \"age\": int(),\n    \"admis\": bool()\n}","note":"Exemple fixe à trois champs. L'atelier permet aussi d'ajouter d'autres champs : c'est une interface plus générale."},{"title":"Remplir les champs","pseudocode":"Procédure REMPLIR(@E : Eleve)\nDébut\n    Lire(E.nom)\n    Lire(E.age)\n    Lire(E.admis)\nFin","python":"def remplir(E):\n    E[\"nom\"] = input(\"Entrer le nom : \")\n    E[\"age\"] = int(input(\"Entrer l'âge : \"))\n    E[\"admis\"] = input(\"Admis (Vrai/Faux) : \") == \"Vrai\"\n    return E","note":""},{"title":"Afficher les champs","pseudocode":"Procédure AFFICHER(E : Eleve)\nDébut\n    Écrire(E.nom)\n    Écrire(E.age)\n    Écrire(E.admis)\nFin","python":"def afficher(E):\n    print(E[\"nom\"])\n    print(E[\"age\"])\n    print(E[\"admis\"])","note":""}]}$afjlesson$::jsonb, '14129cd9e6b4b66257999799884e707886bcfff7f08e6fac3564c168dd5ffe45'),
  ('matrice', $afjlesson${"slug":"matrice","name":"MATRICE","title":"Tableau à deux dimensions","category":"Structures de données","level":"Bases · 3ème Info","method":"base","collection":"general","icon":"▦","summary":"Remplir et afficher une matrice d'entiers.","principle":"Une matrice est organisée en lignes et colonnes. On parcourt ses cellules à l'aide de deux indices.","example":"[[1, 2, 3], [4, 5, 6]] → 2 lignes × 3 colonnes","tags":["matrice","indices","tableau"],"limits":"Maximum 10 × 10 cellules pour garder l'affichage clair.","inputs":[{"name":"matrice","label":"Valeurs de la matrice","kind":"matrix","default":"1, 2, 3\n4, 5, 6","min_value":null,"max_value":null,"options":[],"hint":"Une ligne par rangée, avec les entiers séparés par des virgules."}],"code_sections":[{"title":"Déclarer la matrice — TDNT et TDOG","pseudocode":"TDNT (Tableau de Déclaration des Nouveaux Types)\n    Mat = Tableau de 2 Lignes et 3 Colonnes de type Réels\n\nTDOG (Tableau de Déclaration des Objets Globaux)\n    Objet       Type / Nature\n    M           Mat\n    l, c        Entier\n\nExemple : l ← 2 ; c ← 3","python":"from numpy import array\n\nl = 2\nc = 3\nM = array([[float()] * c] * l)","note":""},{"title":"Remplir manuellement","pseudocode":"Procédure REMPLIR(@M : Mat, l, c : Entier)\nDébut\n    Pour i de 0 à l - 1 Faire\n        Pour j de 0 à c - 1 Faire\n            Lire(M[i, j])\n        Fin Pour\n    Fin Pour\nFin","python":"def remplir(M, l, c):\n    for i in range(l):\n        for j in range(c):\n            M[i, j] = float(input(\"Entrer une valeur : \"))\n    return M","note":""},{"title":"Remplir aléatoirement","pseudocode":"Procédure REMPLIR_ALEATOIRE(@M : Mat, l, c, mini, maxi : Entier)\nDébut\n    Pour i de 0 à l - 1 Faire\n        Pour j de 0 à c - 1 Faire\n            M[i, j] ← Aléa(mini, maxi)\n        Fin Pour\n    Fin Pour\nFin","python":"from random import randint\n\ndef remplir_aleatoire(M, l, c, mini, maxi):\n    for i in range(l):\n        for j in range(c):\n            M[i, j] = randint(mini, maxi)\n    return M","note":""},{"title":"Afficher les cellules","pseudocode":"Procédure AFFICHER(M : Mat, l, c : Entier)\nDébut\n    Pour i de 0 à l - 1 Faire\n        Pour j de 0 à c - 1 Faire\n            Écrire(M[i, j])\n        Fin Pour\n    Fin Pour\nFin","python":"def afficher(M, l, c):\n    for i in range(l):\n        for j in range(c):\n            print(M[i, j])","note":"Le module MATRICE d'origine ne contient pas de tri : nous n'en ajoutons pas."}]}$afjlesson$::jsonb, 'b773674559ee8b608a365979d1c4d9f6386ae58ed1e1b04a0577121f9dcfec25'),
  ('pgcd', $afjlesson${"slug":"pgcd","name":"PGCD","title":"Plus Grand Commun Diviseur","category":"Mathématiques","level":"Bases · 3ème Info","method":"base","collection":"general","icon":"🔢","summary":"Trouver le plus grand diviseur commun de deux entiers.","principle":"On retranche le plus petit entier du plus grand jusqu'à obtenir deux valeurs égales.","example":"PGCD(48, 18) = 6","tags":["entiers","soustractions","boucle"],"limits":"Deux entiers strictement positifs. La méthode par soustractions est volontairement conservée.","inputs":[{"name":"a","label":"Premier entier (a)","kind":"int","default":48,"min_value":1,"max_value":10000,"options":[],"hint":""},{"name":"b","label":"Deuxième entier (b)","kind":"int","default":18,"min_value":1,"max_value":10000,"options":[],"hint":""}],"code_sections":[{"title":"Fonction PGCD par soustractions successives","pseudocode":"Fonction PGCD(a, b : Entier) : Entier\nDébut\n    Tant que a ≠ b Faire\n        Si a > b Alors\n            a ← a - b\n        Sinon\n            b ← b - a\n        Fin Si\n    Fin Tant que\n    Retourner a\nFin","python":"def pgcd(a, b):\n    while a != b:\n        if a > b:\n            a = a - b\n        else:\n            b = b - a\n    return a","note":"On utilise deux entiers strictement positifs, comme dans le programme d'origine."}]}$afjlesson$::jsonb, '8ab73c08a7b4b77396ff3f4951ccf310d128071be96832187abfa361f3d4c602'),
  ('ppcm', $afjlesson${"slug":"ppcm","name":"PPCM","title":"Plus Petit Commun Multiple","category":"Mathématiques","level":"Bases · 3ème Info","method":"base","collection":"general","icon":"➗","summary":"Trouver le plus petit multiple commun de deux entiers.","principle":"On teste les multiples successifs du premier nombre jusqu'à trouver un multiple du second.","example":"PPCM(12, 18) = 36","tags":["multiples","boucle","mod"],"limits":"Deux entiers strictement positifs ; limites d'entrée pour garder une exécution fluide.","inputs":[{"name":"a","label":"Premier entier (a)","kind":"int","default":12,"min_value":1,"max_value":10000,"options":[],"hint":""},{"name":"b","label":"Deuxième entier (b)","kind":"int","default":18,"min_value":1,"max_value":10000,"options":[],"hint":""}],"code_sections":[{"title":"Fonction PPCM par additions successives","pseudocode":"Fonction PPCM(a, b : Entier) : Entier\nDébut\n    m ← a\n    Tant que m mod b ≠ 0 Faire\n        m ← m + a\n    Fin Tant que\n    Retourner m\nFin","python":"def ppcm(a, b):\n    m = a\n    while m % b != 0:\n        m = m + a\n    return m","note":"On utilise deux entiers strictement positifs."}]}$afjlesson$::jsonb, 'cd1b4e0f1d15269fda11760412ddb8581b9ee571513b90080fe90d0fefe9a146'),
  ('som-ch', $afjlesson${"slug":"som-ch","name":"SOM_CH","title":"Somme des chiffres","category":"Traitement","level":"Bases · 3ème Info","method":"base","collection":"general","icon":"🧮","summary":"Calculer la somme de tous les chiffres d'un entier.","principle":"Convertir le nombre en chaîne, parcourir chaque caractère et additionner sa valeur numérique.","example":"SOM_CH(4825) = 19","tags":["chaînes","parcours","addition"],"limits":"Entier positif ou nul ; au plus 9 chiffres dans ce démonstrateur.","inputs":[{"name":"a","label":"Nombre entier (n)","kind":"int","default":4825,"min_value":0,"max_value":999999999,"options":[],"hint":""}],"code_sections":[{"title":"Somme des chiffres d'un nombre","pseudocode":"Fonction SOM_CH(a : Entier) : Entier\nDébut\n    s ← 0\n    ch ← Convch(a)\n    Pour i de 0 à Long(ch) - 1 Faire\n        s ← s + Valeur(ch[i])\n    Fin Pour\n    Retourner s\nFin","python":"def som_ch(a):\n    s = 0\n    ch = str(a)\n    for i in range(len(ch)):\n        s = s + int(ch[i])\n    return s","note":"Comme dans ton code initial : conversion en chaîne puis parcours caractère par caractère."}]}$afjlesson$::jsonb, 'f413797ed3df734effc1483310f3e302ed8d8cbdb07b4a411869f6d466630586'),
  ('tableau', $afjlesson${"slug":"tableau","name":"TABLEAU","title":"Déclarer, remplir et afficher un tableau","category":"Structures de données","level":"Bases · 3ème Info","method":"base","collection":"general","icon":"📊","summary":"Comprendre la déclaration, le remplissage et l’affichage d’un tableau. Tri facultatif.","principle":"Un tableau contient plusieurs valeurs du même type, accessibles par leur indice. On le déclare, on remplit ses cases, puis on les affiche dans l’ordre. Un tri peut être étudié en exercice facultatif.","example":"T = [8, 3, 11, 2, 5] ; T[0] = 8 ; n = 5","tags":["tableau","déclaration","remplissage","affichage","tri","sélection"],"limits":"Maximum 40 entiers pour garder un atelier facile à lire.","inputs":[{"name":"tableau","label":"Éléments du tableau","kind":"int_list","default":"8, 3, 11, 2, 5","min_value":null,"max_value":null,"options":[],"hint":"Séparer les entiers par des virgules."},{"name":"ordre","label":"Tri (facultatif)","kind":"choice","default":"Aucun","min_value":null,"max_value":null,"options":["Aucun","Croissant","Décroissant"],"hint":"Aucun : afficher simplement le tableau. Choisis un ordre pour essayer le tri."}],"code_sections":[{"title":"Déclarer le tableau — TDNT et TDOG","pseudocode":"TDNT (Tableau de Déclaration des Nouveaux Types)\n    Tab = Tableau de 5 Réels\n\nTDOG (Tableau de Déclaration des Objets Globaux)\n    Objet       Type / Nature\n    T           Tab\n    n           Entier\n\nExemple : n ← 5","python":"from numpy import array\n\nn = 5\nT = array([float()] * n)","note":""},{"title":"Remplir manuellement","pseudocode":"Procédure REMPLIR(@T : Tab, n : Entier)\nDébut\n    Pour i de 0 à n - 1 Faire\n        Lire(T[i])\n    Fin Pour\nFin","python":"def remplir(T, n):\n    for i in range(n):\n        T[i] = float(input(\"Entrer T[\" + str(i) + \"] : \"))\n    return T","note":"T et n sont ceux déclarés dans la première étape."},{"title":"Remplir aléatoirement","pseudocode":"Procédure REMPLIR_ALEATOIRE(@T : Tab, n, mini, maxi : Entier)\nDébut\n    Pour i de 0 à n - 1 Faire\n        T[i] ← Aléa(mini, maxi)\n    Fin Pour\nFin","python":"from random import randint\n\ndef remplir_aleatoire(T, n, mini, maxi):\n    for i in range(n):\n        T[i] = randint(mini, maxi)\n    return T","note":""},{"title":"Afficher les éléments","pseudocode":"Procédure AFFICHER(T : Tab, n : Entier)\nDébut\n    Pour i de 0 à n - 1 Faire\n        Écrire(T[i])\n    Fin Pour\nFin","python":"def afficher(T, n):\n    for i in range(n):\n        print(T[i])","note":""},{"title":"Exercice facultatif — trier le tableau (tri par sélection)","pseudocode":"Fonction TRI(T : Tab, n : Entier) : Tab\nDébut\n    Pour i de 0 à n - 2 Faire\n        p ← i\n        Pour j de i + 1 à n - 1 Faire\n            Si T[j] > T[p] Alors\n                p ← j\n            Fin Si\n        Fin Pour\n        Si p ≠ i Alors\n            a ← T[i]\n            T[i] ← T[p]\n            T[p] ← a\n        Fin Si\n    Fin Pour\n    Retourner T\nFin","python":"def tri(T, n):\n    for i in range(n - 1):\n        p = i\n        for j in range(i + 1, n):\n            if T[j] > T[p]:\n                p = j\n        if p != i:\n            a = T[i]\n            T[i] = T[p]\n            T[p] = a\n    return T","note":"Exercice facultatif : le tri d’origine classe dans l’ordre décroissant. Pour trier directement en croissant, remplacer > par < dans ce code ; dans l’atelier, le tri croissant inverse le résultat décroissant."}]}$afjlesson$::jsonb, '3d7ec4494bc0968199f2d648e5d20e3535e8d189972b7aaaf6f2d0c5bcdbf35f'),
  ('verif', $afjlesson${"slug":"verif","name":"VERIF","title":"Appartenance à un intervalle","category":"Traitement","level":"Bases · 3ème Info","method":"base","collection":"general","icon":"📏","summary":"Vérifier si un nombre appartient à un intervalle fermé.","principle":"Le nombre appartient à [min, max] si et seulement si min ≤ nombre ≤ max.","example":"VERIF(7, 2, 10) = Vrai","tags":["conditions","booléen","intervalle"],"limits":"Intervalle fermé : les bornes sont incluses. La borne minimale ne peut pas dépasser la maximale.","inputs":[{"name":"a","label":"Nombre à vérifier","kind":"float","default":7.0,"min_value":null,"max_value":null,"options":[],"hint":""},{"name":"borne_min","label":"Borne minimale","kind":"float","default":2.0,"min_value":null,"max_value":null,"options":[],"hint":""},{"name":"borne_max","label":"Borne maximale","kind":"float","default":10.0,"min_value":null,"max_value":null,"options":[],"hint":""}],"code_sections":[{"title":"Vérifier un intervalle fermé","pseudocode":"Fonction VERIF(a, mini, maxi : Réel) : Booléen\nDébut\n    Si mini ≤ a ≤ maxi Alors\n        Retourner Vrai\n    Sinon\n        Retourner Faux\n    Fin Si\nFin","python":"def VERIF(a, mini, maxi):\n    if mini <= a <= maxi:\n        return True\n    else:\n        return False","note":"La version originale renvoyait True si le test réussissait. Ici, False est écrit explicitement pour faciliter la lecture."}]}$afjlesson$::jsonb, '23a2193b9781bbf0329579c484124fd64d78f8ca840a26dd13b4d7ec05b8d07a')
ON CONFLICT (slug) DO NOTHING;

-- SECURITY INVOKER is essential: Postgres (and Supabase) views otherwise
-- bypass RLS. This read-only projection can never expose private drafts,
-- unapproved revisions, reviewer notes, user IDs or auth information.
CREATE VIEW public.published_methods WITH (security_invoker = true) AS
SELECT r.id, i.id AS implementation_id,
  t.slug AS topic_slug, t.title AS topic_title, t.category, t.school_level,
  i.method_type, r.title, r.explanation, r.pseudocode, r.python_code,
  r.entry_function, r.input_schema, r.test_cases, r.reviewed_at
FROM public.implementations i
JOIN public.revisions r ON r.id = i.published_revision_id
  AND r.implementation_id = i.id
JOIN public.topics t ON t.id = i.topic_id
WHERE r.status = 'published'
  AND r.test_status = 'passed'
  AND r.reviewer_id IS NOT NULL
  AND r.reviewer_id <> r.created_by
  AND r.reviewed_at IS NOT NULL;
REVOKE ALL ON public.published_methods FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.published_methods TO anon, authenticated;
-- The underlying tables already have public SELECT with RLS from migration 001.
-- Never grant the public UPDATE or INSERT on this view or its source tables.
